class World(Model):
    horizon = 1
    state_bounds = {"t": (0, 1), "backlog": (0, 4)}
    events = {"overload": lambda s: 1.0 if s["backlog"] >= 8 else 0.0}

    ARRIVALS = [(0, 0.129842), (1, 0.258261), (2, 0.317032), (4, 0.294865)]
    STAFF = {'staff_1': 1, 'staff_3': 3, 'staff_4': 4}
    WAGE = 8.9
    PENALTY = 9.2

    def initial_state(self):
        return {"t": 0, "backlog": 0}

    def actions(self, state):
        return ['staff_1', 'staff_3', 'staff_4']

    def transition(self, state, action, rng):
        crew = self.STAFF[action]
        r = rng.random()
        count = 0
        for amount, prob in self.ARRIVALS:
            count = amount
            if r < prob:
                break
            r -= prob
        left = max(0, state["backlog"] + count - crew)
        return {"t": state["t"] + 1, "backlog": left}

    def reward(self, state, action, next_state):
        crew = self.STAFF[action]
        return -(self.WAGE * crew + self.PENALTY * next_state["backlog"])

    def is_terminal(self, state, t):
        return state["t"] >= 1

    def outcomes(self, state, action):
        crew = self.STAFF[action]
        return [
            (p, {"t": state["t"] + 1,
                  "backlog": max(0, state["backlog"] + a - crew)})
            for a, p in self.ARRIVALS
        ]

