    horizon = 1
    state_bounds = {"t": (0, 1), "total": (0, 12)}
    events = {"bust": lambda s: 1.0 if s["phase"] == "done" and s["total"] == 0 else 0.0}

    SIDES = 8

    def initial_state(self):
        return {"t": 0, "total": 4, "phase": "play"}

    def actions(self, state):
        return ["roll", "stop"]

    def transition(self, state, action, rng):
        if action == "stop":
            return {"t": state["t"] + 1, "total": state["total"], "phase": "done"}
        die = rng.randint(1, self.SIDES)
        if die == 1:
            return {"t": state["t"] + 1, "total": 0, "phase": "done"}
        return {"t": state["t"] + 1, "total": state["total"] + die, "phase": "play"}

    def reward(self, state, action, next_state):
        if state["phase"] == "play" and next_state["phase"] == "done" and action == "stop":
            return float(next_state["total"])
        return 0.0

    def is_terminal(self, state, t):
        return state["phase"] == "done" or t >= 1

    def outcomes(self, state, action):
        if action == "stop":
            return [(1.0, {"t": state["t"] + 1, "total": state["total"], "phase": "done"})]
        return [
            (0.125, {"t": state["t"] + 1, "total": 0, "phase": "done"}),
            (0.125, {"t": state["t"] + 1, "total": state["total"] + 2, "phase": "play"}),
            (0.125, {"t": state["t"] + 1, "total": state["total"] + 3, "phase": "play"}),
            (0.125, {"t": state["t"] + 1, "total": state["total"] + 4, "phase": "play"}),
            (0.125, {"t": state["t"] + 1, "total": state["total"] + 5, "phase": "play"}),
            (0.125, {"t": state["t"] + 1, "total": state["total"] + 6, "phase": "play"}),
            (0.125, {"t": state["t"] + 1, "total": state["total"] + 7, "phase": "play"}),
            (0.125, {"t": state["t"] + 1, "total": state["total"] + 8, "phase": "play"})
        ]

