from saboragi.wm import Model


class World(Model):
    horizon = 3
    state_bounds = {"t": (0, 3), "wealth": (71, 405)}
    events = {"end_down": lambda s: 1.0 if s["wealth"] < 100 else 0.0}

    PAYOFFS = {
        'lottery_A': [(11, 1.0)],
        'lottery_B': [(40, 0.305012), (-2, 0.694988)],
        'lottery_C': [(100, 0.074057), (-8, 0.925943)]
    }

    def initial_state(self):
        return {"t": 0, "wealth": 100}

    def actions(self, state):
        return ['lottery_A', 'lottery_B', 'lottery_C']

    def transition(self, state, action, rng):
        r = rng.random()
        delta = 0
        for amount, prob in self.PAYOFFS[action]:
            if r < prob:
                delta = amount
                break
            r -= prob
        return {"t": state["t"] + 1, "wealth": state["wealth"] + delta}

    def reward(self, state, action, next_state):
        return float(next_state["wealth"] - state["wealth"])

    def is_terminal(self, state, t):
        return state["t"] >= 3

    def outcomes(self, state, action):
        return [
            (p, {"t": state["t"] + 1, "wealth": state["wealth"] + a})
            for a, p in self.PAYOFFS[action]
        ]

