from saboragi.wm import Model


class World(Model):
    horizon = 10
    state_bounds = {"t": (0, 10), "capital": (-105, 385), "ruined": (0, 1)}
    events = {"catastrophe": lambda s: 1.0 if s["ruined"] == 1 else 0.0}

    SAFE_YIELD = 8
    BOLD_YIELD = 23
    CATA_P = 0.0288
    CATA_LOSS = 250

    def initial_state(self):
        return {"t": 0, "capital": 150, "ruined": 0}

    def actions(self, state):
        return ["project_safe", "project_bold"]

    def transition(self, state, action, rng):
        if action == "project_safe":
            return {
                "t": state["t"] + 1,
                "capital": state["capital"] + self.SAFE_YIELD,
                "ruined": 0,
            }
        if rng.random() < self.CATA_P:
            return {
                "t": state["t"] + 1,
                "capital": state["capital"] - self.CATA_LOSS,
                "ruined": 1,
            }
        return {
            "t": state["t"] + 1,
            "capital": state["capital"] + self.BOLD_YIELD,
            "ruined": 0,
        }

    def reward(self, state, action, next_state):
        return float(next_state["capital"] - state["capital"])

    def is_terminal(self, state, t):
        return state["ruined"] == 1 or state["t"] >= 10

    def outcomes(self, state, action):
        if action == "project_safe":
            return [(
                1.0,
                {"t": state["t"] + 1,
                  "capital": state["capital"] + self.SAFE_YIELD,
                  "ruined": 0},
            )]
        return [
            (
                self.CATA_P,
                {"t": state["t"] + 1,
                  "capital": state["capital"] - self.CATA_LOSS,
                  "ruined": 1},
            ),
            (
                1 - self.CATA_P,
                {"t": state["t"] + 1,
                  "capital": state["capital"] + self.BOLD_YIELD,
                  "ruined": 0},
            ),
        ]

